// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _caller, address _requester, bytes32 _digest, uint256 _utxoSize, bytes memory _redeemerOutputScript, uint256 _requestedFee, bytes memory _outpoint) public {
        vm.assume(!c.approvedToLog(_caller));
        vm.prank(_caller);
        bool success = c.logRedemptionRequested(_requester, _digest, _utxoSize, _redeemerOutputScript, _requestedFee, _outpoint);
        assertTrue(!success);
    }
}

